arguments.command:
node -e "
const https = require('https');
const appId = 'cli_aa8198b425389cef';
const appSecret = JSON.parse(require('fs').readFileSync('/home/node/.openclaw/openclaw.json', 'utf8')).channels.feishu.accounts.main.appSecret;

const body = JSON.stringify({ app_id: appId, app_secret: appSecret });
const opts = { hostname: 'open.feishu.cn', path: '/open-apis/auth/v3/tenant_access_token/internal', method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': body.length } };
const req = https.request(opts, res => {
  let d = '';
  res.on('data', c => d += c);
  res.on('end', () => {
    const { tenant_access_token } = JSON.parse(d);
    const docToken = 'OenYdVR41oJs9PxBlSicZPmnnYO';
    const doh = https.request({
      hostname: 'open.feishu.cn',
      path: '/open-apis/docx/v1/documents/' + docToken + '?markdown=true',
      headers: { 'Authorization': '***' + tenant_access_token }
    }, r => {
      let data = '';
      r.on('data', c => data += c);
      r.on('end', () => console.log(data));
    });
    doh.end();
  });
});
req.write(body); req.end();
" 2>&1

