import { useState } from 'react';
import { useWallet } from './hooks/useWallet';
import { useCase } from './hooks/useCase';
import { CONTRACTS } from './contracts/config';

function App() {
  const [caseId, setCaseId] = useState('');
  const [vote, setVote] = useState(true);
  const [salt, setSalt] = useState('');
  const [txStatus, setTxStatus] = useState(null);
  const [txHash, setTxHash] = useState(null);

  const { address, balance, connecting, error: walletError, connect, disconnect, isConnected, signer } = useWallet();

  const { currentCase, loading: caseLoading, error: caseError, loadCase, commitVote, revealVote, finalizeCase } = useCase(signer);

  const handleCommit = async () => {
    if (!caseId || !salt) { setTxStatus('error: Missing caseId or salt'); return; }
    try {
      setTxStatus('committing...');
      const receipt = await commitVote(Number(caseId), vote, Number(salt));
      setTxStatus('committed');
      setTxHash(receipt.hash);
    } catch (err) {
      setTxStatus('error: ' + err.message);
    }
  };

  const handleReveal = async () => {
    if (!caseId || !salt) { setTxStatus('error: Missing caseId or salt'); return; }
    try {
      setTxStatus('revealing...');
      const receipt = await revealVote(Number(caseId), vote, Number(salt));
      setTxStatus('revealed');
      setTxHash(receipt.hash);
    } catch (err) {
      setTxStatus('error: ' + err.message);
    }
  };

  const handleFinalize = async () => {
    if (!caseId) { setTxStatus('error: Missing caseId'); return; }
    try {
      setTxStatus('finalizing...');
      const receipt = await finalizeCase(Number(caseId));
      setTxStatus('finalized');
      setTxHash(receipt.hash);
    } catch (err) {
      setTxStatus('error: ' + err.message);
    }
  };

  const getStateLabel = (s) => ['COMMIT_OPEN','REVEAL_OPEN','RESOLVED'][s] || 'UNKNOWN';
  const getStateClass = (s) => ['status-commit','status-reveal','status-resolved'][s] || 'bg-neutral-700';

  return (
    <div className="min-h-screen bg-neutral-950 text-white p-8">
      <div className="max-w-4xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2">ECHO v0.4</h1>
          <p className="text-neutral-400">Qitmeer Blockchain Dispute Resolution</p>
        </div>

        <div className="card mb-6">
          <div className="flex items-center justify-between">
            <div>
              {isConnected ? (
                <div>
                  <p className="text-lg font-mono">{address}</p>
                  <p className="text-neutral-400">{balance?.toFixed(4)} MEER</p>
                </div>
              ) : <p className="text-neutral-400">Not connected</p>}
            </div>
            {!isConnected ? (
              <button onClick={connect} disabled={connecting} className="btn-primary">
                {connecting ? 'Connecting...' : 'Connect Wallet'}
              </button>
            ) : (
              <button onClick={disconnect} className="btn-primary">Disconnect</button>
            )}
          </div>
          {walletError && <p className="text-red-400 mt-3">{walletError}</p>}
        </div>

        <div className="card mb-6">
          <h2 className="text-xl font-semibold mb-4">Case Operations</h2>
          <div className="grid grid-cols-2 gap-4 mb-4">
            <div>
              <label className="block text-sm text-neutral-400 mb-1">Case ID</label>
              <input type="number" value={caseId} onChange={(e) => setCaseId(e.target.value)}
                className="w-full bg-neutral-800 border border-neutral-700 rounded px-3 py-2 text-white" />
            </div>
            <div>
              <label className="block text-sm text-neutral-400 mb-1">Salt (number)</label>
              <input type="number" value={salt} onChange={(e) => setSalt(e.target.value)}
                placeholder="123456"
                className="w-full bg-neutral-800 border border-neutral-700 rounded px-3 py-2 text-white" />
            </div>
          </div>
          <div className="mb-4">
            <label className="block text-sm text-neutral-400 mb-1">Vote</label>
            <div className="flex gap-3">
              <button onClick={() => setVote(true)} className={`px-4 py-2 rounded ${vote ? 'bg-green-700' : 'bg-neutral-700'}`}>Approve</button>
              <button onClick={() => setVote(false)} className={`px-4 py-2 rounded ${!vote ? 'bg-red-700' : 'bg-neutral-700'}`}>Reject</button>
            </div>
          </div>
          <div className="flex gap-3">
            <button onClick={() => caseId && loadCase(Number(caseId))} className="btn-primary">Load Case</button>
            <button onClick={handleCommit} className="btn-commit" disabled={!isConnected || caseLoading}>Commit</button>
            <button onClick={handleReveal} className="btn-reveal" disabled={!isConnected || caseLoading}>Reveal</button>
            <button onClick={handleFinalize} className="btn-primary" disabled={!isConnected || caseLoading}>Finalize</button>
          </div>
          {txStatus && (
            <div className={`mt-4 p-3 rounded ${txStatus.startsWith('error') ? 'bg-red-900' : 'bg-green-900'}`}>
              <p>{txStatus}</p>
              {txHash && <p className="text-sm text-neutral-400 mt-1">Tx: {txHash}</p>}
            </div>
          )}
          {caseError && <p className="text-red-400 mt-3">{caseError}</p>}
        </div>

        {currentCase && (
          <div className="card mb-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-semibold">Case #{currentCase.caseId}</h2>
              <span className={`status-badge ${getStateClass(currentCase.state)}`}>{getStateLabel(currentCase.state)}</span>
            </div>
            <div className="grid grid-cols-3 gap-4">
              <div><p className="text-sm text-neutral-400">Commit Deadline</p><p className="font-mono">{currentCase.commitDeadline}</p></div>
              <div><p className="text-sm text-neutral-400">Reveal Deadline</p><p className="font-mono">{currentCase.revealDeadline}</p></div>
              <div><p className="text-sm text-neutral-400">Commits / Reveals</p><p className="font-mono">{currentCase.commitCount} / {currentCase.revealCount}</p></div>
            </div>
          </div>
        )}

        <div className="card">
          <h2 className="text-xl font-semibold mb-4">Contract Addresses</h2>
          <div className="space-y-2">
            {Object.entries(CONTRACTS).map(([name, addr]) => (
              <div key={name} className="flex justify-between"><span className="text-neutral-400">{name}</span><span className="font-mono text-sm">{addr}</span></div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;

import { useState, useCallback } from 'react';
import { BrowserProvider } from 'ethers';
import { CONTRACTS, CHAIN_ID, CHAIN_NAME } from '../contracts/config';

const QITMEER_RPC = 'https://qng.rpc.qitmeer.io';

export function useWallet() {
  const [provider, setProvider] = useState(null);
  const [signer, setSigner] = useState(null);
  const [address, setAddress] = useState(null);
  const [balance, setBalance] = useState(null);
  const [connecting, setConnecting] = useState(false);
  const [error, setError] = useState(null);

  const connect = useCallback(async () => {
    setConnecting(true);
    setError(null);

    try {
      // Check for ethereum window object
      if (!window.ethereum) {
        throw new Error('No wallet detected. Please install MetaMask or a Qitmeer-compatible wallet.');
      }

      // Request account access
      const accounts = await window.ethereum.request({ 
        method: 'eth_requestAccounts' 
      });

      if (!accounts || accounts.length === 0) {
        throw new Error('No accounts found. Please unlock your wallet.');
      }

      const addr = accounts[0];

      // Create ethers provider
      const web3Provider = new BrowserProvider(window.ethereum);
      const web3Signer = await web3Provider.getSigner();

      // Get network
      const network = await web3Provider.getNetwork();

      // Check if correct chain
      if (Number(network.chainId) !== CHAIN_ID) {
        console.warn(`Connected to chain ${network.chainId}, expected ${CHAIN_ID} (${CHAIN_NAME})`);
      }

      // Get balance
      const balanceWei = await web3Provider.getBalance(addr);
      const balanceFormatted = Number(balanceWei) / 1e18;

      setProvider(web3Provider);
      setSigner(web3Signer);
      setAddress(addr);
      setBalance(balanceFormatted);

      console.log('Wallet connected:', addr, 'Balance:', balanceFormatted, 'MEER');

    } catch (err) {
      console.error('Wallet connection error:', err);
      setError(err.message || 'Failed to connect wallet');
    } finally {
      setConnecting(false);
    }
  }, []);

  const disconnect = useCallback(() => {
    setProvider(null);
    setSigner(null);
    setAddress(null);
    setBalance(null);
    setError(null);
  }, []);

  const switchToQitmeer = useCallback(async () => {
    if (!window.ethereum) return;

    try {
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: '0x' + CHAIN_ID.toString(16) }], // 0x32D = 813
      });
    } catch (switchError) {
      // Chain not added, try adding
      if (switchError.code === 4902) {
        try {
          await window.ethereum.request({
            method: 'wallet_addEthereumChain',
            params: [{
              chainId: '0x32D',
              chainName: CHAIN_NAME,
              rpcUrls: ['https://qng.rpc.qitmeer.io'],
              blockExplorerUrls: ['https://qng.meerscan.io'],
              nativeCurrency: {
                name: 'MEER',
                symbol: 'MEER',
                decimals: 18,
              },
            }],
          });
        } catch (addError) {
          console.error('Failed to add Qitmeer chain:', addError);
        }
      }
    }
  }, []);

  // Listen for account changes
  if (window.ethereum && !window.ethereum._eventsBound) {
    window.ethereum.on('accountsChanged', (accounts) => {
      if (accounts.length === 0) {
        disconnect();
      } else {
        setAddress(accounts[0]);
      }
    });

    window.ethereum.on('chainChanged', () => {
      window.location.reload();
    });

    window.ethereum._eventsBound = true;
  }

  return {
    provider,
    signer,
    address,
    balance,
    connecting,
    error,
    connect,
    disconnect,
    switchToQitmeer,
    isConnected: !!address,
  };
}

import { useState, useEffect } from 'react';
import { Contract, keccak256, solidityPacked } from 'ethers';
import { CONTRACTS } from '../contracts/config';
import { AGENTJURY_ABI } from '../contracts/abi';

const { AgentJury } = CONTRACTS;

export function useCase(signer) {
  const [currentCase, setCurrentCase] = useState(null);
  const [commitments, setCommitments] = useState({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Load case info
  const loadCase = async (caseId) => {
    if (!signer) return;

    setLoading(true);
    setError(null);

    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);
      const caseData = await jury.getCase(caseId);

      const [
        evidenceHash, 
        commitDeadline, 
        revealDeadline, 
        state, 
        commitCount, 
        revealCount, 
        jurorCount, 
        resolved, 
        appealed
      ] = caseData;

      setCurrentCase({
        caseId,
        evidenceHash,
        commitDeadline: Number(commitDeadline),
        revealDeadline: Number(revealDeadline),
        state: Number(state), // 0=COMMIT, 1=REVEAL, 2=RESOLVED
        commitCount: Number(commitCount),
        revealCount: Number(revealCount),
        jurorCount: Number(jurorCount),
        resolved,
        appealed,
      });

      console.log('Case loaded:', caseId, 'State:', Number(state), 'CommitCount:', Number(commitCount), 'RevealCount:', Number(revealCount));

    } catch (err) {
      console.error('Failed to load case:', err);
      setError(err.message || 'Failed to load case');
    } finally {
      setLoading(false);
    }
  };

  // Commit vote
  const commitVote = async (caseId, vote, salt) => {
    if (!signer) throw new Error('Wallet not connected');

    setLoading(true);
    setError(null);

    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);
      const address = await signer.getAddress();

      // Generate commit hash: keccak256(abi.encodePacked(vote, salt, caseId, sender))
      const commitHash = keccak256(
        solidityPacked(['bool', 'uint256', 'uint256', 'address'], [vote, BigInt(salt), caseId, address])
      );

      console.log('Committing vote:', { caseId, vote, salt, address, commitHash });

      const tx = await jury.juryCommit(caseId, commitHash, BigInt(salt));
      console.log('Commit tx sent:', tx.hash);

      const receipt = await tx.wait();
      console.log('Commit confirmed:', receipt.hash);

      return receipt;

    } catch (err) {
      console.error('Commit failed:', err);
      const errorMsg = err.message || 'Commit failed';
      setError(errorMsg);
      throw new Error(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  // Reveal vote
  const revealVote = async (caseId, vote, salt) => {
    if (!signer) throw new Error('Wallet not connected');

    setLoading(true);
    setError(null);

    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);

      console.log('Revealing vote:', { caseId, vote, salt });

      const tx = await jury.juryReveal(caseId, vote, BigInt(salt));
      console.log('Reveal tx sent:', tx.hash);

      const receipt = await tx.wait();
      console.log('Reveal confirmed:', receipt.hash);

      return receipt;

    } catch (err) {
      console.error('Reveal failed:', err);
      const errorMsg = err.message || 'Reveal failed';
      setError(errorMsg);
      throw new Error(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  // Finalize case
  const finalizeCase = async (caseId) => {
    if (!signer) throw new Error('Wallet not connected');

    setLoading(true);
    setError(null);

    try {
      const jury = new Contract(AgentJury, AGENTJURY_ABI, signer);

      console.log('Finalizing case:', caseId);

      const tx = await jury.finalizeCase(caseId);
      console.log('Finalize tx sent:', tx.hash);

      const receipt = await tx.wait();
      console.log('Finalize confirmed:', receipt.hash);

      return receipt;

    } catch (err) {
      console.error('Finalize failed:', err);
      const errorMsg = err.message || 'Finalize failed';
      setError(errorMsg);
      throw new Error(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return {
    currentCase,
    commitments,
    loading,
    error,
    loadCase,
    commitVote,
    revealVote,
    finalizeCase,
  };
}

// ECHO v0.4 Contract Addresses - Qitmeer Mainnet (Chain ID 813)
